class Framework {
  private handlers: Record<string, Function[]> = {};
  register(event: string, handler: () => void) {
    (this.handlers[event] ||= []).push(handler);
  }
  trigger(event: string) {
    (this.handlers[event] || []).forEach(h => h());
  }
}

// app code calls framework.register('start', () => doStartup());

// Version A: framework defines Hook interface and calls plugin methods
interface Hook { onStart(): void }
class Framework {
  private hooks: Hook[] = [];
  register(h: Hook) { this.hooks.push(h) }
  start() { this.hooks.forEach(h => h.onStart()) }
}

// Version B: framework offers global registry that plugins push plain functions into
class Registry {
  static handlers: Function[] = []
  static register(fn: Function) { this.handlers.push(fn) }
}
function frameworkStart() { Registry.handlers.forEach(fn => fn()) }
